1	#!/usr/bin/env node
2	
3	import crypto from "node:crypto";
4	import http from "node:http";
5	import os from "node:os";
6	import path from "node:path";
7	import process from "node:process";
8	import { fileURLToPath } from "node:url";
9	import WebSocket, { WebSocketServer } from "ws";
10	
11	import {
12	  buildBonjourAdvertisementArgs,
13	  startBonjourAdvertisement,
14	} from "./dock-relay-bonjour.mjs";
15	import {
16	  DEFAULT_HISTORY_APP_SERVER_WS,
17	  DEFAULT_PHONE_AUTH,
18	  DEFAULT_RELAY_LISTEN_HOST,
19	  DOCK_RELAY_PORT,
20	  JSON_RPC_MAX_MESSAGE_BYTES,
21	  RELAY_SHUTDOWN_PROCESS_TIMEOUT_MS,
22	  RELAY_SHUTDOWN_SOCKET_TIMEOUT_MS,
23	  RELAY_VERSION,
24	  UPSTREAM_POOL_LIMITS,
25	  UPSTREAM_RECONNECT_ATTEMPTS,
26	  UPSTREAM_RECONNECT_DELAY_MS,
27	  UPSTREAM_RECONNECT_JITTER_MS,
28	} from "./dock-relay-constants.mjs";
29	import {
30	  defaultRelayLogger,
31	  installRelayFatalHandlers,
32	} from "./dock-relay-logger.mjs";
33	import {
34	  createRelayObservability,
35	  extractTraceContextFromParams,
36	} from "./dock-relay-observability.mjs";
37	import { JsonRpcWebSocketClient } from "./dock-relay-json-rpc-client.mjs";
38	import {
39	  DEFAULT_REALTIME_TRANSCRIPTION_DELAY,
40	  DEFAULT_REALTIME_TRANSCRIPTION_ENDPOINT,
41	  DEFAULT_REALTIME_TRANSCRIPTION_LANGUAGE,
42	  DEFAULT_REALTIME_TRANSCRIPTION_MODEL,
