49	} from "./dock-relay-status.mjs";
50	import {
51	  ARCHIVE_RESYNC_METHOD,
52	  ARCHIVE_SUBSCRIBE_METHOD,
53	  DOCK_RESYNC_METHOD,
54	  DOCK_SUBSCRIBE_METHOD,
55	} from "./dock-relay-state-subscriptions.mjs";
56	import { relayStateEngineForConfig } from "./dock-relay-state-engine.mjs";
57	import {
58	  loadDotEnvFile,
59	  parsePhoneAuthMode,
60	  readToken,
61	} from "./dock-relay-env.mjs";
62	import {
63	  assertHumanThreadID,
64	  aggregateThreadRead,
65	  archiveThread,
66	  attentionFlagsForServerRequest,
67	  endpointForThread,
68	  initializeClient,
69	  listThreadTurns,
70	  liveStatusCacheForConfig,
71	  mergeActiveFlags,
72	  parseLimit,
73	  pendingRequestsForActiveThread,
74	  preferThread,
75	  sanitizeRelayFields,
76	  sessionRouterForConfig,
77	  statusPriority,
78	  unarchiveThread,
79	} from "./dock-relay-thread-data.mjs";
80	import { threadMatchesSourceKinds } from "./dock-relay-source-filter.mjs";
81	import { UpstreamConnectionPool } from "./dock-relay-upstream-pool.mjs";
82	
83	function shortHash(value) {
84	  if (!value) {
85	    return null;
86	  }
87	  return crypto.createHash("sha256").update(String(value)).digest("hex").slice(0, 12);
88	}
89	
90	function parseArgs(argv) {
91	  const result = {};
92	  for (let index = 0; index < argv.length; index += 1) {
93	    const arg = argv[index];
94	    if (!arg.startsWith("--")) {
95	      throw new Error(`unexpected argument: ${arg}`);
96	    }
97	    const key = arg.slice(2);
98	    const value = argv[index + 1];
99	    if (!value || value.startsWith("--")) {
100	      throw new Error(`missing value for --${key}`);
101	    }
102	    result[key] = value;
103	    index += 1;
104	  }
105	  return result;
106	}
107	
108	function parseLiveEndpoints(value) {
109	  if (!value) {
110	    return [];
111	  }
112	  return String(value)
113	    .split(",")
114	    .map((entry) => entry.trim())
115	    .filter(Boolean)
116	    .map((entry) => {
117	      const separator = entry.indexOf("=");
118	      if (separator > 0) {
119	        return {
120	          label: entry.slice(0, separator).trim(),
121	          url: entry.slice(separator + 1).trim(),
122	        };
123	      }
124	      return {
125	        label: entry,
126	        url: entry,
127	      };
128	    })
129	    .filter((endpoint) => endpoint.url);
130	}
131	
132	function relayLogger(config) {
133	  return config?.logger || defaultRelayLogger;
134	}
135	
136	function jsonRpcError(id, code, message, data = undefined) {
137	  const error = {
138	    code: Number.isInteger(code) ? code : -32000,
139	    message,
140	  };
141	  if (data !== undefined) {
142	    error.data = data;
143	  }
144	  return { jsonrpc: "2.0", id, error };
145	}
146	
147	function jsonRpcErrorCode(error) {
148	  return Number.isInteger(error?.code) ? error.code : -32000;
149	}
150	
151	function jsonRpcResult(id, result) {
152	  return { jsonrpc: "2.0", id, result };
153	}
154	
155	function relayError(message, code = -32000, data = undefined) {
156	  const error = new Error(message);
157	  error.code = code;
158	  if (data !== undefined) {
159	    error.data = data;
160	  }
161	  return error;
162	}
163	
164	function sendJson(ws, value) {
165	  if (ws.readyState === WebSocket.OPEN) {
166	    ws.send(JSON.stringify(value));
167	  }
168	}
169	
170	function isWebSocketOpen(ws) {
171	  return ws?.readyState === WebSocket.OPEN;
172	}
173	
174	function isSessionActive(session, downstreamWs, generation) {
175	  return !session.closing
176	    && session.generation === generation
177	    && isWebSocketOpen(downstreamWs);
178	}
179	
180	function throwIfSessionInactive(session, downstreamWs, generation) {
181	  if (!isSessionActive(session, downstreamWs, generation)) {
182	    throw new Error("downstream session closed");
183	  }
184	}
185	
186	function platformOs() {
187	  if (process.platform === "darwin") {
188	    return "macos";
189	  }
190	  return process.platform;
191	}
192	
193	function sleep(ms) {
194	  return new Promise((resolve) => {
195	    setTimeout(resolve, ms);
196	  });
197	}
198	
199	function liveResumeParams(params) {
200	  return {
201	    ...params,
202	    excludeTurns: true,
203	  };
204	}
205	
206	function threadIDFromParams(params) {
207	  const threadId = params?.threadId;
208	  return typeof threadId === "string" && threadId.length > 0 ? threadId : null;
209	}
210	
211	function assertFocusedRequestTargetsBoundThread(session, method, params = {}) {
212	  if (!session.upstream?.isOpen()) {
213	    throw new Error(`${method} requires thread/resume on this connection first`);
214	  }
215	  const boundThreadId = session.resumeParams?.threadId || null;
216	  const requestedThreadId = threadIDFromParams(params);
217	  if (!boundThreadId || !requestedThreadId) {
218	    throw relayError(`${method} requires threadId matching the active thread`, -32602, {
219	      subsystem: "live-upstream",
220	      reason: "missing_thread_id",
221	    });
222	  }
223	  if (requestedThreadId !== boundThreadId) {
224	    throw relayError(`${method} threadId does not match the active thread`, -32602, {
225	      subsystem: "live-upstream",
226	      reason: "thread_mismatch",
227	      requestedThreadIDHash: shortHash(requestedThreadId),
228	      activeThreadIDHash: shortHash(boundThreadId),
229	    });
230	  }
231	  if (session.acceptedHumanThreadId !== boundThreadId) {
232	    throw relayError(`${method} requires a human-started active thread`, -32602, {
233	      subsystem: "live-upstream",
234	      reason: "thread_not_human_verified",
235	      activeThreadIDHash: shortHash(boundThreadId),
236	    });
237	  }
238	}
239	
240	function assertResumeResultMatchesRequestedThread(result, requestedThreadId) {
241	  const actualThreadId = result?.thread?.id;
242	  if (actualThreadId !== requestedThreadId) {
243	    throw relayError("thread/resume returned a different thread", -32000, {
244	      subsystem: "live-upstream",
245	      reason: "resume_thread_mismatch",
246	      requestedThreadIDHash: shortHash(requestedThreadId),
247	      actualThreadIDHash: shortHash(actualThreadId),
248	    });
249	  }
250	}
251	
252	function upstreamReconnectDelayMs(attempt) {
253	  const exponentialDelay = UPSTREAM_RECONNECT_DELAY_MS * (2 ** Math.max(0, attempt - 1));
254	  const jitter = Math.floor(Math.random() * (UPSTREAM_RECONNECT_JITTER_MS + 1));
255	  return exponentialDelay + jitter;
256	}
257	
258	async function resumeThread(config, params = {}, session, downstreamWs) {
259	  if (!params.threadId) {
260	    throw new Error("thread/resume requires threadId");
261	  }
262	  const resumeParams = liveResumeParams(params);
263	  await assertHumanThreadID(config, resumeParams.threadId);
264	
265	  session.generation += 1;
266	  const generation = session.generation;
267	  session.retryTask = null;
268	  session.pendingServerRequests?.clear();
269	  session.upstream?.close();
270	  session.upstream = null;
271	  session.acceptedHumanThreadId = null;
272	
273	  const logger = relayLogger(config);
274	  const endpoint = await sessionRouterForConfig(config).endpointForThread(resumeParams.threadId);
275	  throwIfSessionInactive(session, downstreamWs, generation);
276	  const client = makeSessionUpstreamClient(config, endpoint, session, downstreamWs, generation);
277	
278	  try {
279	    await initializeClient(client);
280	    throwIfSessionInactive(session, downstreamWs, generation);
281	    const result = await client.request("thread/resume", resumeParams);
282	    throwIfSessionInactive(session, downstreamWs, generation);
283	    assertResumeResultMatchesRequestedThread(result, resumeParams.threadId);
284	    session.upstream = client;
285	    session.resumeParams = { ...resumeParams };
286	    session.acceptedHumanThreadId = resumeParams.threadId;
287	    session.endpoint = endpoint;
288	    logger.info("thread_resume.succeeded", {
289	      subsystem: "live-upstream",
290	      hostId: config.hostId,
291	      threadId: resumeParams.threadId,
292	      endpointUrl: endpoint.url,
293	    });
294	    return result;
295	  } catch (error) {
296	    client.close();
297	    logger.warn("thread_resume.failed", {
298	      threadId: params.threadId,
299	      endpointUrl: endpoint.url,
300	      error,
301	    });
302	    config.statusTracker?.recordUpstreamError(error, {
303	      subsystem: "live-upstream",
304	      threadId: params.threadId,
305	      endpointUrl: endpoint.url,
306	    });
307	    throw error;
308	  }
309	}
310	
311	function makeSessionUpstreamClient(config, endpoint, session, downstreamWs, generation) {
312	  let client;
313	  client = new JsonRpcWebSocketClient(endpoint.url, {
314	    bearerToken: endpoint.bearerToken || null,
315	    logger: relayLogger(config),
316	    onNotification: (message) => {
317	      if (isSessionActive(session, downstreamWs, generation)) {
318	        sendJson(downstreamWs, message);
319	      }
320	    },
321	    onRequest: (message) => {
322	      if (isSessionActive(session, downstreamWs, generation)) {
323	        session.pendingServerRequests.set(String(message.id), {
324	          generation,
325	          threadId: message?.params?.threadId || session.resumeParams?.threadId || null,
326	          method: message.method,
327	        });
328	        sendJson(downstreamWs, message);
329	      }
330	    },
331	    onClose: () => {
332	      handleSessionUpstreamClose(config, session, downstreamWs, client);
333	    },
334	  });
335	  return client;
336	}
337	
338	function handleSessionUpstreamClose(config, session, downstreamWs, closedClient) {
339	  if (session.closing || session.upstream !== closedClient) {
340	    return;
341	  }
342	  session.upstream = null;
343	  session.pendingServerRequests?.clear();
344	  if (!isWebSocketOpen(downstreamWs)) {
345	    return;
346	  }
347	  if (!session.endpoint || !session.resumeParams?.threadId) {
348	    config.statusTracker?.recordUpstreamError(new Error("upstream closed"), {
349	      subsystem: "live-upstream",
350	    });
351	    downstreamWs.close(1011, "upstream closed");
352	    return;
353	  }
354	  if (session.retryTask) {
355	    return;
356	  }
357	  session.retryTask = recoverSessionUpstream(config, session, downstreamWs, session.generation);
358	}
359	
360	async function recoverSessionUpstream(config, session, downstreamWs, generation) {
361	  const endpoint = session.endpoint;
362	  const resumeParams = session.resumeParams;
363	  let lastError = null;
364	  config.statusTracker?.recordReconnect({
365	    active: true,
366	    attempts: 0,
367	  });
368	
369	  for (let attempt = 1; attempt <= UPSTREAM_RECONNECT_ATTEMPTS; attempt += 1) {
370	    if (session.closing || session.generation !== generation || !isWebSocketOpen(downstreamWs)) {
371	      session.retryTask = null;
372	      config.statusTracker?.recordReconnect({
373	        active: false,
374	        attempts: attempt - 1,
375	      });
376	      return;
377	    }
378	
379	    const client = makeSessionUpstreamClient(config, endpoint, session, downstreamWs, generation);
380	    try {
381	      await initializeClient(client);
382	      const result = await client.request("thread/resume", resumeParams);
383	      assertResumeResultMatchesRequestedThread(result, resumeParams.threadId);
384	      if (!isSessionActive(session, downstreamWs, generation)) {
385	        client.close();
386	        session.retryTask = null;
387	        return;
388	      }
389	      session.upstream = client;
390	      session.retryTask = null;
391	      config.statusTracker?.recordReconnect({
392	        active: false,
393	        attempts: attempt,
394	      });
395	      relayLogger(config).info("upstream.recovery_succeeded", {
396	        threadId: resumeParams.threadId,
397	        endpointUrl: endpoint.url,
398	        attempt,
399	      });
400	      return;
401	    } catch (error) {
402	      lastError = error;
403	      config.statusTracker?.recordUpstreamError(error, {
404	        subsystem: "live-upstream",
405	        threadId: resumeParams.threadId,
406	        endpointUrl: endpoint.url,
407	        attempt,
408	      });
409	      client.close();
410	      const delayMs = upstreamReconnectDelayMs(attempt);
411	      config.statusTracker?.recordReconnect({
412	        active: true,
413	        attempts: attempt,
414	        nextRetryAt: new Date(Date.now() + delayMs).toISOString(),
415	      });
416	      await sleep(delayMs);
417	    }
418	  }
419	
420	  session.retryTask = null;
421	  config.statusTracker?.recordReconnect({
422	    active: false,
423	    attempts: UPSTREAM_RECONNECT_ATTEMPTS,
424	  });
425	  relayLogger(config).error("upstream.recovery_failed", {
426	    threadId: resumeParams.threadId,
427	    endpointUrl: endpoint.url,
428	    error: lastError,
429	  });
430	  if (!session.closing && session.generation === generation && isWebSocketOpen(downstreamWs)) {
431	    downstreamWs.close(1011, "upstream recovery failed");
432	  }
433	}
434	
435	async function forwardToActiveUpstream(config, session, method, params = {}) {
436	  assertFocusedRequestTargetsBoundThread(session, method, params);
437	  relayLogger(config).info("focused_request.route_verified", {
438	    subsystem: "live-upstream",
439	    method,
440	    endpointUrl: session.endpoint?.url || null,
441	    threadIDHash: shortHash(params.threadId),
442	    activeThreadIDHash: shortHash(session.resumeParams?.threadId),
443	    generation: session.generation,
444	  });
445	  return session.upstream.request(method, params);
446	}
447	
448	async function handleRequest(config, method, params, session, downstreamWs) {
449	  switch (method) {
450	    case "initialize":
451	      return {
452	        userAgent: `codex_dock_relay/${RELAY_VERSION} (${os.type()} ${os.release()}; ${os.arch()})`,
453	        codexHome: config.codexHome || process.env.CODEX_HOME || path.join(os.homedir(), ".codex"),
454	        platformFamily: "unix",
455	        platformOs: platformOs(),
456	        relayInstanceID: config.hostId,
457	      };
458	    case DOCK_SUBSCRIBE_METHOD:
459	      return relayStateEngineForConfig(config).subscribeDock({ session, downstreamWs, sendJson });
460	    case DOCK_RESYNC_METHOD:
461	      return relayStateEngineForConfig(config).resyncDock({ downstreamWs, sendJson });
462	    case ARCHIVE_SUBSCRIBE_METHOD:
463	      return relayStateEngineForConfig(config).subscribeArchive({ session, downstreamWs, sendJson });
464	    case ARCHIVE_RESYNC_METHOD:
465	      return relayStateEngineForConfig(config).resyncArchive({ downstreamWs, sendJson });
466	    case "thread/read":
467	      return aggregateThreadRead(config, params || {});
468	    case "thread/turns/list":
469	      return listThreadTurns(config, params || {});
470	    case "thread/resume":
471	      return resumeThread(config, params || {}, session, downstreamWs);
472	    case "thread/archive":
473	    {
474	      const result = await archiveThread(config, params || {});
475	      await relayStateEngineForConfig(config).handleArchiveMutation({
476	        threadId: params?.threadId,
477	        archived: true,
478	      });
479	      return result;
480	    }
481	    case "thread/unarchive":
482	    {
483	      const result = await unarchiveThread(config, params || {});
484	      await relayStateEngineForConfig(config).handleArchiveMutation({
485	        threadId: params?.threadId,
486	        archived: false,
487	      });
488	      return result;
489	    }
490	    case "audio/transcription/start":
491	      return session.realtimeTranscription.start(params || {});
492	    case "audio/transcription/append":
493	      return session.realtimeTranscription.append(params || {});
494	    case "audio/transcription/commit":
495	      return session.realtimeTranscription.commit(params || {});
496	    case "audio/transcription/cancel":
497	      return session.realtimeTranscription.cancel(params || {});
498	    case "turn/start":
499	    case "turn/steer":
500	    case "turn/interrupt":
501	      return forwardToActiveUpstream(config, session, method, params || {});
502	    default:
503	      throw Object.assign(new Error(`unsupported method: ${method}`), {
504	        code: -32601,
505	      });
506	  }
507	}
508	
509	function assertAuthorized(request, token) {
510	  const header = request.headers.authorization || "";
511	  return header === `Bearer ${token}`;
512	}
513	
514	function isPhoneRequestAuthorized(request, config) {
515	  if (config.phoneAuth === "none") {
516	    return true;
517	  }
518	  return assertAuthorized(request, config.relayBearerToken);
519	}
520	
521	function isLoopbackRemoteAddress(value) {
522	  return value === "127.0.0.1"
523	    || value === "::1"
524	    || value === "::ffff:127.0.0.1";
525	}
526	
527	function writeLoopbackOnlyResponse(request, response) {
528	  if (isLoopbackRemoteAddress(request.socket?.remoteAddress)) {
529	    return false;
