82	class StateReconciler {
83	  constructor({
84	    engine,
85	    intervalMs = RELAY_STATE_RECONCILE_INTERVAL_MS,
86	    debounceMs = RELAY_STATE_RECONCILE_DEBOUNCE_MS,
87	  }) {
88	    this.engine = engine;
89	    this.intervalMs = intervalMs;
90	    this.debounceMs = debounceMs;
91	    this.timer = null;
92	    this.debounceTimer = null;
93	    this.inFlight = null;
94	  }
95	
96	  start() {
97	    if (this.timer) {
98	      return;
99	    }
100	    this.schedule({ reason: "boot", immediate: false });
101	    this.timer = setInterval(() => {
102	      this.schedule({ reason: "periodic", immediate: false });
103	    }, this.intervalMs);
104	    this.timer.unref?.();
105	  }
106	
107	  async stop() {
108	    if (this.timer) {
109	      clearInterval(this.timer);
110	      this.timer = null;
111	    }
112	    if (this.debounceTimer) {
113	      clearTimeout(this.debounceTimer);
114	      this.debounceTimer = null;
115	    }
116	    if (this.inFlight) {
117	      await this.inFlight.catch(() => null);
118	    }
119	  }
120	
121	  schedule({ reason, immediate = false } = {}) {
122	    if (immediate) {
123	      if (this.debounceTimer) {
124	        clearTimeout(this.debounceTimer);
125	        this.debounceTimer = null;
126	      }
127	      return this.run(reason || "manual");
128	    }
129	    if (this.debounceTimer) {
130	      clearTimeout(this.debounceTimer);
131	    }
132	    this.debounceTimer = setTimeout(() => {
133	      this.debounceTimer = null;
134	      this.run(reason || "debounced").catch((error) => {
135	        this.engine.logger?.warn?.("state.reconcile_failed", { reason, error });
136	      });
137	    }, this.debounceMs);
138	    this.debounceTimer.unref?.();
139	    return Promise.resolve(null);
140	  }
141	
142	  async run(reason = "manual") {
143	    if (this.inFlight) {
144	      return this.inFlight;
145	    }
146	    this.inFlight = this.engine.reconcileDock({ reason }).finally(() => {
147	      this.inFlight = null;
