317	        complete,
318	        error: reconciliationScope.error || null,
319	        previousCards: previousDockCards,
320	      });
321	      const freshness = this.store.freshnessForHost(host.id);
322	      const totalRows = this.store.listDockCards({ hostID: host.id }).totalRows;
323	      const truthComplete = freshness.status === "fresh"
