360	  freshnessForHost(hostID) {
361	    const rows = this.db.prepare(`
362	      SELECT complete, last_attempt_at, last_sync_at, last_error
363	      FROM sync_scopes
364	      WHERE host_id = ?
365	    `).all(hostID);
366	    if (rows.length === 0) {
367	      return {
368	        status: "unknown",
369	        lastAttemptAt: null,
370	        lastSyncAt: null,
371	        lastError: null,
372	      };
373	    }
374	    const failed = rows.find((row) => row.complete === 0);
375	    const unprovenCards = this.db.prepare(`
376	      SELECT COUNT(*) AS count
377	      FROM threads
378	      WHERE host_id = ?
379	        AND (active_scope_present = 1 OR archived_scope_present = 1)
380	        AND (activity_proof_status != 'proven' OR completeness != 'complete' OR freshness_status != 'fresh')
381	    `).get(hostID).count;
382	    const latestAttempt = rows.map((row) => row.last_attempt_at).filter(Boolean).sort().at(-1) || null;
383	    const latestSync = rows.map((row) => row.last_sync_at).filter(Boolean).sort().at(-1) || null;
384	    return {
385	      status: failed || Number(unprovenCards || 0) > 0 ? "stale" : "fresh",
386	      lastAttemptAt: latestAttempt,
387	      lastSyncAt: latestSync,
388	      lastError: failed?.last_error || (Number(unprovenCards || 0) > 0 ? "card activity proof incomplete" : null),
