463	  applyDockReconciliation({ host, cards, scopes = [], complete = true, error = null, previousCards = null }) {
464	    const atMs = nowMs();
465	    const at = new Date(atMs).toISOString();
466	    return this.transaction(() => {
467	      this.upsertHost(host, at);
468	      const previousRows = Array.isArray(previousCards)
469	        ? previousCards
470	        : this.listDockCards({ hostID: host.id }).cards;
471	      const previousByID = new Map(previousRows.map((row) => [row.id, row]));
472	      const existingRows = this.db.prepare(`
473	        SELECT thread_id, archive_state, freshness_status, updated_at
474	        FROM threads
475	        WHERE host_id = ?
476	      `).all(host.id);
477	      const existingByThreadID = new Map(existingRows.map((row) => [row.thread_id, row]));
478	      const nextByID = new Map();
479	      const upsertCards = [];
480	      const deleteCardIDs = [];
481	
482	      cards.forEach((card) => {
483	        const existing = existingByThreadID.get(card.threadID);
484	        if (isFreshLocalArchiveMutation(existing, atMs)) {
485	          return;
486	        }
487	        const cardWithOrder = {
488	          ...card,
489	          orderKey: card.orderKey || activityOrderKey(card.activityAtMs || Date.now(), card.threadID),
490	          archiveState: "active",
491	        };
492	        nextByID.set(cardWithOrder.id, cardWithOrder);
493	        const previous = previousByID.get(cardWithOrder.id);
494	        if (sortedJSONString(previous) !== sortedJSONString(cardWithOrder)) {
495	          upsertCards.push(cardWithOrder);
496	        }
497	        this.upsertThreadCard(host.id, cardWithOrder, {
498	          archiveState: "active",
499	          activeScopePresent: true,
500	          at,
501	        });
502	      });
503	
504	      if (complete) {
505	        for (const previous of previousRows) {
506	          if (!nextByID.has(previous.id)) {
507	            deleteCardIDs.push(previous.id);
508	            this.markThreadInactive(host.id, previous.threadID, at);
509	          }
510	        }
511	      }
512	
513	      for (const scope of scopes) {
514	        this.recordSyncScope(host.id, scope, at);
515	      }
516	      if (scopes.length === 0) {
517	        this.recordSyncScope(host.id, {
518	          name: "active:interactiveDefault",
519	          archived: false,
520	          sourceScope: "interactiveDefault",
521	          complete,
522	          error,
523	        }, at);
524	      }
525	
526	      const seq = this.recordChange({
527	        view: DOCK_VIEW,
528	        hostID: host.id,
529	        changeType: "dock-reconcile",
530	        payload: {
531	          upsertCount: upsertCards.length,
532	          deleteCount: deleteCardIDs.length,
533	          complete,
534	        },
535	        at,
536	      });
537	      this.pruneChanges();
538	      return { seq, upsertCards, deleteCardIDs };
539	    });
540	  }
