775	      FROM live_leases
776	      WHERE host_id = ?
777	        AND expires_at_ms >= ?
778	        AND expired_published_at IS NULL
779	        AND EXISTS (
780	          SELECT 1
781	          FROM threads t
782	          WHERE t.host_id = live_leases.host_id
783	            AND t.thread_id = live_leases.thread_id
784	            AND ${HUMAN_APP_FACING_THREAD_SQL_FOR_ALIAS}
785	        )
786	    `).get(hostID, Number(atMs));
787	    const expiresAtMs = Number(row?.expires_at_ms || 0);
