232	    private func reload(showLoading: Bool) async {
233	        guard !hosts.isEmpty else {
234	            DockLog.dock.warning("dock reload skipped reason=no_hosts")
235	            return
236	        }
237	        guard !isLoading else {
238	            DockLog.dock.debug("dock reload skipped reason=already_loading")
239	            return
240	        }
241	
242	        let startedAt = Date()
243	        let signpostState = DockSignpost.dock.beginInterval("dock.reload")
244	        DockLog.dock.notice("dock stream reload started hosts=\(self.hosts.count, privacy: .public) show_loading=\(showLoading, privacy: .public)")
245	        isLoading = true
246	        defer {
247	            DockSignpost.dock.endInterval("dock.reload", signpostState)
248	            isLoading = false
249	        }
250	
251	        let hostViewModels = hosts.map(DockHostViewModel.init)
252	        if showLoading {
253	            state = .loading(hostViewModels)
254	            screenStore.setLoading(hosts: hostViewModels)
255	            publishConnectivity(for: state)
256	        }
257	
258	        do {
259	            localMetadata = try await metadataEngine.load()
260	            DockLog.persistence.debug("dock metadata loaded entries=\(self.localMetadata.count, privacy: .public)")
261	        } catch {
262	            localMetadata = [:]
263	            await metadataEngine.replace(localMetadata)
264	            DockLog.persistence.warning("dock metadata load failed error=\(DockLog.errorSummary(error), privacy: .public)")
265	        }
266	
267	        await dataEngine?.updateLocalMetadata(localMetadata)
268	        await dataEngine?.ensureHosts()
269	        await synchronizeStreams()
270	        await migrateMetadataHostAliases()
271	        await publishSnapshot()
272	        if case let .loaded(snapshot) = state {
273	            DockLog.dock.notice("dock stream reload finished hosts=\(self.hosts.count, privacy: .public) rows=\(snapshot.rowCount, privacy: .public) duration_ms=\(DockLog.milliseconds(since: startedAt), privacy: .public)")
274	        }
275	    }
