277	    private func synchronizeStreams() async {
278	        let validHostIDs = Set(hosts.map(\.id))
279	        for hostID in streamConnections.keys where !validHostIDs.contains(hostID) {
280	            streamTasks[hostID]?.cancel()
281	            streamTasks[hostID] = nil
282	            let connection = streamConnections.removeValue(forKey: hostID)
283	            await connection?.close()
284	        }
285	
286	        for host in hosts {
287	            if let connection = streamConnections[host.id] {
288	                await resync(host: host, connection: connection)
289	            } else {
290	                await openStream(host: host)
291	            }
292	        }
293	    }
