295	    private func openStream(host: DockHostConfiguration) async {
296	        guard let dataEngine else {
297	            return
298	        }
299	
300	        await dataEngine.markChecking(host: host)
301	        await publishSnapshot()
302	        var openedConnection: (any ThreadCardStreamConnection)?
303	        do {
304	            let connection = try await streamClient.connect(to: host)
305	            openedConnection = connection
306	            streamConnections[host.id] = connection
307	            let snapshot = try await connection.subscribe()
308	            try await applySubscribedSnapshot(snapshot, host: host, connection: connection)
309	            startUpdateTask(host: host, connection: connection)
310	            await migrateMetadataHostAliases()
311	            await publishSnapshot()
312	        } catch {
313	            streamTasks[host.id]?.cancel()
314	            streamTasks[host.id] = nil
315	            streamConnections[host.id] = nil
316	            await openedConnection?.close()
317	            DockLog.dock.warning("dock stream open failed host_id=\(host.id, privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
318	            await dataEngine.markFailure(Self.mapRequestFailure(error), host: host)
319	            await publishSnapshot()
320	        }
321	    }
