323	    private func resync(host: DockHostConfiguration, connection: any ThreadCardStreamConnection) async {
324	        guard let dataEngine else {
325	            return
326	        }
327	
328	        do {
329	            let snapshot = try await connection.resync()
330	            try await applyResyncSnapshot(snapshot, host: host)
331	            await migrateMetadataHostAliases()
332	            await publishSnapshot()
333	            let rowCount = await dataEngine.rowCount(for: host)
334	            DockLog.dock.notice("dock stream resync finished host_id=\(host.id, privacy: .public) seq=\(snapshot.seq, privacy: .public) rows=\(rowCount, privacy: .public)")
335	        } catch {
336	            DockLog.dock.warning("dock stream resync failed host_id=\(host.id, privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
337	            await dataEngine.markFailure(Self.mapRequestFailure(error), host: host)
338	            await publishSnapshot()
339	        }
340	    }
