342	    private func startUpdateTask(host: DockHostConfiguration, connection: any ThreadCardStreamConnection) {
343	        streamTasks[host.id]?.cancel()
344	        streamTasks[host.id] = Task { [weak self, host, connection] in
345	            do {
346	                for try await update in connection.updates() {
347	                    await self?.handleStreamUpdate(update, host: host, connection: connection)
348	                }
349	                if !Task.isCancelled {
350	                    await self?.handleStreamFailure(
351	                        DockRequestFailure.offline("Relay stream closed"),
352	                        host: host,
353	                        connection: connection
354	                    )
355	                }
356	            } catch is CancellationError {
357	                return
358	            } catch {
359	                await self?.handleStreamFailure(error, host: host, connection: connection)
360	            }
361	        }
362	    }
