364	    private func handleStreamUpdate(
365	        _ update: ThreadCardStreamUpdateDTO,
366	        host: DockHostConfiguration,
367	        connection: any ThreadCardStreamConnection
368	    ) async {
369	        guard let dataEngine else {
370	            return
371	        }
372	
373	        let result = await dataEngine.applyUpdate(update, host: host)
374	        if case .needsResync(let reason) = result {
375	            DockLog.dock.warning("dock stream resync needed host_id=\(host.id, privacy: .public) reason=\(reason.rawValue, privacy: .public) update_kind=\(update.kind.rawValue, privacy: .public) seq=\(update.seq, privacy: .public)")
376	            await resync(host: host, connection: connection)
377	        } else {
378	            await migrateMetadataHostAliases()
379	            await publishSnapshot()
380	            let rowCount = await dataEngine.rowCount(for: host)
381	            DockLog.dock.info("dock stream update applied host_id=\(host.id, privacy: .public) update_kind=\(update.kind.rawValue, privacy: .public) seq=\(update.seq, privacy: .public) rows=\(rowCount, privacy: .public)")
382	            if let freshness = update.freshness,
383	               freshness.status != .fresh,
384	               rowCount > 0 {
385	                DockLog.dock.notice("dock stream rows retained host_id=\(host.id, privacy: .public) freshness=\(freshness.status.rawValue, privacy: .public) rows=\(rowCount, privacy: .public)")
386	            }
387	        }
388	    }
