390	    private func applySubscribedSnapshot(
391	        _ snapshot: ThreadCardStreamUpdateDTO,
392	        host: DockHostConfiguration,
393	        connection: any ThreadCardStreamConnection
394	    ) async throws {
395	        guard let dataEngine else {
396	            return
397	        }
398	
399	        switch await dataEngine.applySnapshot(snapshot, host: host) {
400	        case .applied:
401	            return
402	        case .needsResync(let reason):
403	            DockLog.dock.warning("dock stream subscribe snapshot rejected host_id=\(host.id, privacy: .public) reason=\(reason.rawValue, privacy: .public) seq=\(snapshot.seq, privacy: .public)")
404	            let resynced = try await connection.resync()
405	            try await applyResyncSnapshot(resynced, host: host)
406	        }
407	    }
