409	    private func applyResyncSnapshot(
410	        _ snapshot: ThreadCardStreamUpdateDTO,
411	        host: DockHostConfiguration
412	    ) async throws {
413	        guard let dataEngine else {
414	            return
415	        }
416	
417	        switch await dataEngine.applySnapshot(snapshot, host: host) {
418	        case .applied:
419	            return
420	        case .needsResync(let reason):
421	            throw DockRequestFailure.error("Dock stream resync returned incompatible data (\(reason.rawValue)).")
422	        }
423	    }
