425	    private func handleStreamFailure(
426	        _ error: Error,
427	        host: DockHostConfiguration,
428	        connection: any ThreadCardStreamConnection
429	    ) async {
430	        DockLog.dock.warning("dock stream update failed host_id=\(host.id, privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
431	        streamConnections[host.id] = nil
432	        streamTasks[host.id] = nil
433	        await connection.close()
434	        await dataEngine?.markFailure(Self.mapRequestFailure(error), host: host)
435	        await publishSnapshot()
436	        let rowCount = await dataEngine?.rowCount(for: host) ?? 0
437	        if rowCount > 0 {
438	            DockLog.dock.notice("dock stream rows retained host_id=\(host.id, privacy: .public) freshness=offline rows=\(rowCount, privacy: .public)")
439	        }
440	        scheduleReconnect(host: host)
441	    }
