607	    private nonisolated static func mapRequestFailure(_ error: Error) -> DockRequestFailure {
608	        if let failure = error as? DockRequestFailure {
609	            return failure
610	        }
611	        if let clientError = error as? AppServerClientError {
612	            switch clientError {
613	            case .disconnected, .notConnected, .requestTimedOut, .transport:
614	                return .offline(clientError.localizedDescription)
615	            case .duplicateRequestID,
616	                 .malformedMessage,
617	                 .requestCancelled,
618	                 .responseDecoding,
619	                 .server,
620	                 .unexpectedServerRequest,
621	                 .unmatchedResponse:
622	                return .error(clientError.localizedDescription)
623	            }
624	        }
625	        return .error(error.localizedDescription)
626	    }
