3	enum ThreadCardTableResyncReason: String, Equatable, Sendable {
4	    case schemaMismatch
5	    case streamContract
6	    case epochMismatch
7	    case sequenceGap
8	}
9	
10	enum ThreadCardTableApplyResult: Equatable, Sendable {
11	    case applied
12	    case needsResync(ThreadCardTableResyncReason)
13	}
14	
15	struct ThreadCardTable: Equatable, Sendable {
16	    private struct HostStreamState: Equatable, Sendable {
17	        var epoch: String?
18	        var seq: Int64
19	        var status: DockHostLoadStatus
20	        var freshness: DockStreamFreshnessDTO?
21	        var complete: Bool
22	        var totalRows: Int?
23	        var window: DockStreamWindowDTO?
24	        var streamHosts: [DockStreamHostDTO]
25	        var cardsByID: [String: DockThreadCardDTO]
26	
27	        init(status: DockHostLoadStatus = .checking) {
28	            self.epoch = nil
29	            self.seq = 0
30	            self.status = status
31	            self.freshness = nil
32	            self.complete = false
33	            self.totalRows = nil
34	            self.window = nil
35	            self.streamHosts = []
36	            self.cardsByID = [:]
37	        }
38	    }
39	
40	    private var statesByHostID: [String: HostStreamState] = [:]
41	
42	    mutating func reset(hosts: [DockHostConfiguration]) {
43	        statesByHostID = Dictionary(
44	            uniqueKeysWithValues: hosts.map { host in
45	                (host.id, HostStreamState())
46	            }
47	        )
48	    }
49	
50	    mutating func ensureHosts(_ hosts: [DockHostConfiguration]) {
51	        let validHostIDs = Set(hosts.map(\.id))
52	        statesByHostID = statesByHostID.filter { validHostIDs.contains($0.key) }
53	        for host in hosts where statesByHostID[host.id] == nil {
54	            statesByHostID[host.id] = HostStreamState()
55	        }
56	    }
57	
58	    mutating func markChecking(host: DockHostConfiguration) {
59	        var state = statesByHostID[host.id] ?? HostStreamState()
60	        let rowCount = state.cardsByID.count
61	        state.status = rowCount > 0
62	            ? .partial(rowCount: rowCount, message: "Reconnecting")
63	            : .checking
64	        statesByHostID[host.id] = state
65	    }
66	
67	    mutating func markFailure(_ failure: DockRequestFailure, host: DockHostConfiguration) {
68	        var state = statesByHostID[host.id] ?? HostStreamState()
69	        let message = failure.localizedDescription
70	        let rowCount = state.cardsByID.count
71	        switch failure {
72	        case .offline:
73	            state.status = rowCount > 0 ? .partial(rowCount: rowCount, message: "Offline: \(message)") : .offline(message)
74	            state.freshness = DockStreamFreshnessDTO(status: .offline, lastError: message)
75	        case .error:
76	            state.status = rowCount > 0 ? .partial(rowCount: rowCount, message: message) : .error(message)
77	            state.freshness = DockStreamFreshnessDTO(status: .error, lastError: message)
78	        }
79	        statesByHostID[host.id] = state
80	    }
81	
82	    mutating func applySnapshot(_ update: ThreadCardStreamUpdateDTO, host: DockHostConfiguration) -> ThreadCardTableApplyResult {
83	        guard acceptsSchemaVersion(update.schemaVersion) else {
84	            return .needsResync(.schemaMismatch)
85	        }
86	        guard acceptsStreamContract(update) else {
87	            return .needsResync(.streamContract)
88	        }
89	
90	        var state = statesByHostID[host.id] ?? HostStreamState()
91	        state.epoch = update.epoch
92	        state.seq = update.seq
93	        state.freshness = update.freshness
94	        state.complete = update.complete ?? false
95	        state.totalRows = update.totalRows
96	        state.window = update.window
97	        state.streamHosts = update.hosts ?? []
98	        state.cardsByID = Dictionary(
99	            uniqueKeysWithValues: (update.cards ?? [])
100	                .filter(\.isAppFacingHumanThreadCard)
101	                .map { card in
102	                    (card.id, card)
103	                }
104	        )
105	        state.status = hostStatus(
106	            freshness: update.freshness,
107	            rowCount: state.cardsByID.count,
108	            complete: state.complete,
109	            totalRows: state.totalRows
110	        )
111	        statesByHostID[host.id] = state
112	        return .applied
113	    }
114	
115	    mutating func applyUpdate(_ update: ThreadCardStreamUpdateDTO, host: DockHostConfiguration) -> ThreadCardTableApplyResult {
116	        guard update.kind != .snapshot else {
117	            return applySnapshot(update, host: host)
118	        }
119	
120	        guard acceptsSchemaVersion(update.schemaVersion) else {
121	            return .needsResync(.schemaMismatch)
122	        }
123	        guard acceptsStreamContract(update) else {
124	            return .needsResync(.streamContract)
125	        }
126	
127	        guard var state = statesByHostID[host.id],
128	              state.epoch == update.epoch else {
129	            return .needsResync(.epochMismatch)
130	        }
131	
132	        switch update.kind {
133	        case .heartbeat:
134	            guard state.seq == update.seq else {
135	                return .needsResync(.sequenceGap)
136	            }
137	        case .delta:
138	            guard update.baseSeq == state.seq else {
139	                return .needsResync(.sequenceGap)
140	            }
141	            for host in update.upsertHosts ?? [] {
142	                state.streamHosts.removeAll { $0.id == host.id }
143	                state.streamHosts.append(host)
144	            }
145	            for card in (update.upsertCards ?? []).filter(\.isAppFacingHumanThreadCard) {
146	                state.cardsByID[card.id] = card
147	            }
148	            for cardID in update.deleteCardIDs ?? [] {
149	                state.cardsByID.removeValue(forKey: cardID)
150	            }
151	            state.seq = update.seq
152	        case .snapshot:
153	            break
154	        }
155	
156	        state.freshness = update.freshness ?? state.freshness
157	        state.complete = update.complete ?? state.complete
158	        state.totalRows = update.totalRows ?? state.totalRows
159	        state.window = update.window ?? state.window
160	        state.status = hostStatus(
161	            freshness: state.freshness,
162	            rowCount: state.cardsByID.count,
163	            complete: state.complete,
164	            totalRows: state.totalRows
165	        )
166	        statesByHostID[host.id] = state
167	        return .applied
168	    }
169	
170	    private func acceptsSchemaVersion(_ schemaVersion: Int?) -> Bool {
171	        guard let schemaVersion else {
172	            return false
173	        }
174	        return schemaVersion == CodexDockConstants.Dock.streamSchemaVersion
175	    }
176	
177	    private func acceptsStreamContract(_ update: ThreadCardStreamUpdateDTO) -> Bool {
178	        guard update.view == .dock else {
179	            return false
180	        }
181	        switch update.kind {
182	        case .snapshot:
183	            guard let complete = update.complete,
184	                  let totalRows = update.totalRows,
185	                  let window = update.window else {
186	                return false
187	            }
188	            return acceptsWindowContract(
189	                complete: complete,
190	                totalRows: totalRows,
191	                window: window,
192	                cardCount: update.cards?.count ?? 0
193	            )
194	        case .delta, .heartbeat:
195	            if update.complete == false {
196	                guard let totalRows = update.totalRows,
197	                      let window = update.window else {
198	                    return false
199	                }
200	                return acceptsWindowContract(
201	                    complete: false,
202	                    totalRows: totalRows,
203	                    window: window,
204	                    cardCount: update.upsertCards?.count ?? 0
205	                )
206	            }
207	            return true
208	        }
209	    }
210	
211	    private func acceptsWindowContract(
212	        complete: Bool,
213	        totalRows: Int,
214	        window: DockStreamWindowDTO,
215	        cardCount: Int
216	    ) -> Bool {
217	        guard totalRows >= 0,
218	              window.offset >= 0,
219	              window.limit >= 0,
220	              window.rowCount >= 0,
221	              window.rowCount == cardCount else {
222	            return false
223	        }
224	        if let nextOffset = window.nextOffset,
225	           nextOffset <= window.offset {
226	            return false
227	        }
228	        return complete || window.rowCount <= totalRows
229	    }
230	
231	    func snapshot(
232	        hosts: [DockHostConfiguration],
233	        localMetadata: [LocalThreadMetadataKey: LocalThreadMetadata],
234	        now: @escaping @Sendable () -> Date
235	    ) -> DockSnapshot {
236	        DockRenderProjector(now: now).snapshot(
237	            from: renderInput(hosts: hosts),
238	            localMetadata: localMetadata
239	        )
240	    }
241	
242	    func renderInput(hosts: [DockHostConfiguration]) -> DockRenderInput {
243	        let hostStates = hosts.map { host in
244	            DockHostStateViewModel(
245	                host: DockHostViewModel(host: host),
246	                status: statesByHostID[host.id]?.status ?? .checking
247	            )
248	        }
249	        let statuses = Dictionary(
250	            uniqueKeysWithValues: hostStates.map { ($0.host.id, $0.status) }
251	        )
252	        return DockRenderInput(
253	            hosts: hosts,
254	            hostStates: hostStates,
255	            hostIdentityResolver: DockHostIdentityResolver(
256	                hosts: hosts,
257	                observations: identityObservations(hosts: hosts),
258	                hostStatuses: statuses
259	            ),
260	            cardsByHostID: Dictionary(
261	                uniqueKeysWithValues: hosts.map { host in
262	                    (host.id, sortedCards(for: host))
263	                }
264	            ),
265	            isPartial: hosts.contains(where: isCheckingOrPartial)
266	        )
267	    }
268	
269	    func rowCount(for host: DockHostConfiguration) -> Int {
270	        statesByHostID[host.id]?.cardsByID.count ?? 0
271	    }
272	
273	    func hostIdentityResolver(hosts: [DockHostConfiguration]) -> DockHostIdentityResolver {
274	        DockHostIdentityResolver(
275	            hosts: hosts,
276	            observations: identityObservations(hosts: hosts),
277	            hostStatuses: Dictionary(
278	                uniqueKeysWithValues: hosts.map { host in
279	                    (host.id, statesByHostID[host.id]?.status ?? .checking)
280	                }
281	            )
282	        )
283	    }
284	
285	    private func sortedCards(for host: DockHostConfiguration) -> [DockThreadCardDTO] {
286	        guard let state = statesByHostID[host.id] else {
287	            return []
288	        }
289	        return Array(state.cardsByID.values)
290	            .sorted { lhs, rhs in
291	                if lhs.orderKey != rhs.orderKey {
292	                    return lhs.orderKey < rhs.orderKey
293	                }
294	                return lhs.id < rhs.id
295	            }
296	    }
297	
298	    private func identityObservations(hosts: [DockHostConfiguration]) -> [DockHostIdentityObservation] {
299	        hosts.flatMap { host in
300	            guard let state = statesByHostID[host.id] else {
301	                return [DockHostIdentityObservation]()
302	            }
303	            let hostObservations = state.streamHosts.map { streamHost in
304	                DockHostIdentityObservation(configuredHostID: host.id, streamHost: streamHost)
305	            }
306	            let cardObservations = state.cardsByID.values.map { card in
307	                DockHostIdentityObservation(configuredHostID: host.id, card: card)
308	            }
309	            return hostObservations + cardObservations
310	        }
311	    }
312	
313	    private func isCheckingOrPartial(_ host: DockHostConfiguration) -> Bool {
314	        let status = statesByHostID[host.id]?.status
315	        if case .checking = status {
316	            return true
317	        }
318	        return status?.isPartial == true
319	    }
320	
321	    private func hostStatus(
322	        freshness: DockStreamFreshnessDTO?,
323	        rowCount: Int,
324	        complete: Bool,
325	        totalRows: Int?
326	    ) -> DockHostLoadStatus {
327	        if !complete {
328	            let visibleRows = rowCount
329	            let knownTotal = max(totalRows ?? visibleRows, visibleRows)
330	            let message = knownTotal > visibleRows
331	                ? "Showing \(visibleRows) of \(knownTotal)"
332	                : "Partial window"
333	            return .partial(rowCount: visibleRows, message: message)
334	        }
335	        guard let freshness else {
336	            return rowCount == 0 ? .checking : .loaded(rowCount: rowCount)
337	        }
338	        switch freshness.status {
339	        case .fresh:
340	            return rowCount == 0 ? .empty : .loaded(rowCount: rowCount)
341	        case .stale:
342	            return .partial(rowCount: rowCount, message: freshness.lastError ?? "Stale")
343	        case .offline:
344	            let message = freshness.lastError ?? "Offline"
345	            return rowCount > 0 ? .partial(rowCount: rowCount, message: "Offline: \(message)") : .offline(message)
346	        case .error:
347	            let message = freshness.lastError ?? "Error"
348	            return rowCount > 0 ? .partial(rowCount: rowCount, message: message) : .error(message)
349	        case .unknown:
350	            return rowCount == 0 ? .checking : .partial(rowCount: rowCount, message: "Refreshing")
351	        }
352	    }
