356	function classifyRelayRequestError(method, error) {
357	  if (error?.code === -32043 && error?.data) {
358	    return {
359	      subsystem: "human-filter",
360	      retryable: false,
361	      ...error.data,
362	    };
363	  }
364	  if (error?.code === -32001) {
365	    return {
366	      subsystem: "upstream-overload",
367	      retryable: true,
368	      overload: true,
369	    };
370	  }
371	  if (error?.data?.subsystem) {
372	    return {
373	      ...error.data,
374	      retryable: error.data.retryable ?? error.code !== -32602,
375	    };
376	  }
377	  if (method === "thread/read"
378	    || method === "thread/turns/list"
379	    || method === "thread/archive" || method === "thread/unarchive") {
380	    return {
381	      subsystem: "history",
382	      retryable: true,
383	    };
384	  }
385	  if (method === "thread/resume" || method === "turn/start" || method === "turn/steer" || method === "turn/interrupt") {
386	    return {
387	      subsystem: "live-upstream",
388	      retryable: true,
389	    };
390	  }
391	  if (String(method || "").startsWith("audio/transcription/")) {
392	    return {
393	      subsystem: "transcription",
394	      retryable: error?.code !== -32602,
395	    };
396	  }
397	  return undefined;
398	}
