75	    private func groups(
76	        for rows: [DockRowViewModel]
77	    ) -> [DockProjectionGroupViewModel] {
78	        switch options.lens {
79	        case .newest:
80	            return []
81	        case .host:
82	            return hostGroups(for: rows)
83	        case .branch:
84	            return branchGroups(for: rows)
85	        }
86	    }
