338	    private func groupPrecedes(_ lhs: DockProjectionGroupViewModel, _ rhs: DockProjectionGroupViewModel) -> Bool {
339	        if let lhsOrderKey = lhs.orderKey,
340	           let rhsOrderKey = rhs.orderKey,
341	           lhsOrderKey != rhsOrderKey {
342	            return lhsOrderKey < rhsOrderKey
343	        }
344	        if lhs.orderKey != nil {
345	            return true
346	        }
347	        if rhs.orderKey != nil {
348	            return false
349	        }
350	
351	        let titleOrder = lhs.title.localizedCaseInsensitiveCompare(rhs.title)
352	        if titleOrder != .orderedSame {
353	            return titleOrder == .orderedAscending
354	        }
355	        return lhs.id < rhs.id
356	    }
