358	    private func rowPrecedesByRelayOrder(_ lhs: DockRowViewModel, _ rhs: DockRowViewModel) -> Bool {
359	        // The relay owns card ordering. Swift may filter and group rows, but it
360	        // must not rebuild recency from timestamps or local status.
361	        if let lhsOrderKey = lhs.orderKey,
362	           let rhsOrderKey = rhs.orderKey,
363	           lhsOrderKey != rhsOrderKey {
364	            return lhsOrderKey < rhsOrderKey
365	        }
366	        if lhs.orderKey != nil {
367	            return true
368	        }
369	        if rhs.orderKey != nil {
370	            return false
371	        }
372	
373	        let titleOrder = lhs.title.localizedCaseInsensitiveCompare(rhs.title)
374	        if titleOrder != .orderedSame {
375	            return titleOrder == .orderedAscending
376	        }
377	
378	        return "\(lhs.id.hostID)::\(lhs.id.threadID)" < "\(rhs.id.hostID)::\(rhs.id.threadID)"
379	    }
