381	    private func pinnedRowPrecedes(_ lhs: DockRowViewModel, _ rhs: DockRowViewModel) -> Bool {
382	        if let lhsOrder = lhs.pinnedOrder,
383	           let rhsOrder = rhs.pinnedOrder,
384	           lhsOrder != rhsOrder {
385	            return lhsOrder < rhsOrder
386	        }
387	        if lhs.pinnedOrder != nil {
388	            return true
389	        }
390	        if rhs.pinnedOrder != nil {
391	            return false
392	        }
393	
394	        let lhsPinnedAt = lhs.pinnedAt ?? Date.distantPast
395	        let rhsPinnedAt = rhs.pinnedAt ?? Date.distantPast
396	        if lhsPinnedAt != rhsPinnedAt {
397	            return lhsPinnedAt < rhsPinnedAt
398	        }
399	
400	        return "\(lhs.id.hostID)::\(lhs.id.threadID)" < "\(rhs.id.hostID)::\(rhs.id.threadID)"
401	    }
402	
403	    private func normalizedQuery(_ value: String) -> String {
404	        value.trimmingCharacters(in: .whitespacesAndNewlines)
405	    }
406	
407	    private func uniqueSorted(_ values: [String]) -> [String] {
408	        Set(values).sorted { lhs, rhs in
409	            lhs.localizedCaseInsensitiveCompare(rhs) == .orderedAscending
410	        }
411	    }
412	}
