134	struct ThreadEventIndex: Sendable {
135	    private var events: [ThreadEvent] = []
136	
137	    mutating func replace(with events: [ThreadEvent]) {
138	        self.events = ThreadEventDisplayOrder.newestFirst(events)
139	    }
140	
141	    mutating func appendOrMerge(_ event: ThreadEvent) {
142	        guard let index = events.firstIndex(where: { $0.id == event.id }) else {
143	            appendOrMergeByStreamItem(event)
144	            return
145	        }
146	
147	        let mergedEvent: ThreadEvent
148	        if events[index].isStreamingDelta, event.isStreamingDelta, events[index].kind == event.kind {
149	            mergedEvent = events[index].mergingStreamingDelta(event)
150	        } else {
151	            mergedEvent = event
152	        }
153	        events.remove(at: index)
154	        insertInOrder(mergedEvent)
155	    }
156	
157	    func eventsNewestFirst() -> [ThreadEvent] {
158	        events
159	    }
160	
161	    private mutating func appendOrMergeByStreamItem(_ event: ThreadEvent) {
162	        guard let mergeKey = ThreadEventStreamMergeKey(event),
163	              let index = events.firstIndex(where: { ThreadEventStreamMergeKey($0) == mergeKey }) else {
164	            insertInOrder(event)
165	            return
166	        }
167	
168	        let existing = events[index]
169	        let mergedEvent: ThreadEvent?
170	        if existing.isStreamingDelta, event.isStreamingDelta, existing.kind == event.kind {
171	            mergedEvent = existing.mergingStreamingDelta(event)
172	        } else if existing.isStreamingDelta || !event.isStreamingDelta {
173	            mergedEvent = event
174	        } else {
175	            // Ignore late deltas after a full item snapshot has already arrived.
176	            mergedEvent = nil
177	        }
178	
179	        guard let mergedEvent else {
180	            return
181	        }
182	        events.remove(at: index)
183	        insertInOrder(mergedEvent)
184	    }
185	
186	    private mutating func insertInOrder(_ event: ThreadEvent) {
187	        guard let index = events.firstIndex(where: { existing in
188	            ThreadEventDisplayOrder.shouldPrecedeInNewestFirstOrder(event, existing)
189	        }) else {
190	            events.append(event)
191	            return
192	        }
193	        events.insert(event, at: index)
194	    }
195	}
