197	private struct ThreadEventStreamMergeKey: Equatable {
198	    let turnID: String
199	    let itemID: String
200	    let kind: ThreadEventKind
201	    let visibility: ThreadEventVisibilityCategory
202	
203	    init?(_ event: ThreadEvent) {
204	        guard let turnID = event.turnID,
205	              let itemID = event.itemID else {
206	            return nil
207	        }
208	        switch event.visibilityCategory {
209	        case .message, .thinking, .tooling:
210	            self.turnID = turnID
211	            self.itemID = itemID
212	            self.kind = event.kind
213	            self.visibility = event.visibilityCategory
214	        case .request, .system, .unknown:
215	            return nil
216	        }
217	    }
