360	async function recoverSessionUpstream(config, session, downstreamWs, generation) {
361	  const endpoint = session.endpoint;
362	  const resumeParams = session.resumeParams;
363	  let lastError = null;
364	  config.statusTracker?.recordReconnect({
365	    active: true,
366	    attempts: 0,
367	  });
368	
369	  for (let attempt = 1; attempt <= UPSTREAM_RECONNECT_ATTEMPTS; attempt += 1) {
370	    if (session.closing || session.generation !== generation || !isWebSocketOpen(downstreamWs)) {
371	      session.retryTask = null;
372	      config.statusTracker?.recordReconnect({
373	        active: false,
374	        attempts: attempt - 1,
375	      });
376	      return;
377	    }
378	
379	    const client = makeSessionUpstreamClient(config, endpoint, session, downstreamWs, generation);
380	    try {
381	      await initializeClient(client);
382	      const result = await client.request("thread/resume", resumeParams);
383	      assertResumeResultMatchesRequestedThread(result, resumeParams.threadId);
384	      if (!isSessionActive(session, downstreamWs, generation)) {
385	        client.close();
386	        session.retryTask = null;
387	        return;
388	      }
389	      session.upstream = client;
390	      session.retryTask = null;
391	      config.statusTracker?.recordReconnect({
392	        active: false,
393	        attempts: attempt,
394	      });
395	      relayLogger(config).info("upstream.recovery_succeeded", {
396	        threadId: resumeParams.threadId,
397	        endpointUrl: endpoint.url,
398	        attempt,
399	      });
400	      return;
401	    } catch (error) {
402	      lastError = error;
403	      config.statusTracker?.recordUpstreamError(error, {
404	        subsystem: "live-upstream",
405	        threadId: resumeParams.threadId,
406	        endpointUrl: endpoint.url,
407	        attempt,
408	      });
409	      client.close();
410	      const delayMs = upstreamReconnectDelayMs(attempt);
411	      config.statusTracker?.recordReconnect({
412	        active: true,
413	        attempts: attempt,
414	        nextRetryAt: new Date(Date.now() + delayMs).toISOString(),
415	      });
416	      await sleep(delayMs);
417	    }
418	  }
419	
420	  session.retryTask = null;
421	  config.statusTracker?.recordReconnect({
422	    active: false,
423	    attempts: UPSTREAM_RECONNECT_ATTEMPTS,
424	  });
425	  relayLogger(config).error("upstream.recovery_failed", {
426	    threadId: resumeParams.threadId,
427	    endpointUrl: endpoint.url,
428	    error: lastError,
429	  });
430	  if (!session.closing && session.generation === generation && isWebSocketOpen(downstreamWs)) {
431	    downstreamWs.close(1011, "upstream recovery failed");
432	  }
433	}
